import pandas as pd
import numpy as np
from typing import List, Dict, Any

class StatsService:
    def __init__(self, transactions: List[Dict[str, Any]]):
        self.df = pd.DataFrame(transactions)
        if not self.df.empty:
            self.df['date'] = pd.to_datetime(self.df['date'])
            # Sort by date to ensure cumulative balance is correct
            self.df = self.df.sort_values('date')

    def get_monthly_summary(self) -> List[Dict[str, Any]]:
        if self.df.empty:
            return []

        # We need to calculate the running balance first
        self.df['running_balance'] = self.df['amount'].cumsum()

        self.df['month'] = self.df['date'].dt.strftime('%Y-%m')

        # Group by month
        # For income/spend, we sum the monthly deltas
        # For balance, we take the LAST balance of that month
        summary = self.df.groupby('month').agg({
            'amount': [
                ('income', lambda x: round(float(x[x > 0].sum()), 2)),
                ('spend', lambda x: round(float(abs(x[x < 0].sum())), 2))
            ],
            'running_balance': [('balance', lambda x: round(float(x.iloc[-1]), 2))]
        }).reset_index()

        # Flatten multi-index columns
        summary.columns = ['month', 'income', 'spend', 'balance']

        summary = summary.sort_values('month')

        # Standardize for JSON
        return summary.replace({np.nan: None}).to_dict(orient='records')

    def get_category_breakdown(self) -> List[Dict[str, Any]]:
        if self.df.empty:
            return []

        # Filter only expenses
        expenses = self.df[self.df['amount'] < 0].copy()

        if expenses.empty:
            return []

        # Group by Category and Subcategory
        # We want: [ { category: 'Food', amount: 100, subcategories: [{name: 'Groceries', amount: 80}, ...] }, ... ]

        # 1. Total per category
        cat_group = expenses.groupby('category')['amount'].sum().abs().reset_index()
        cat_group = cat_group.sort_values('amount', ascending=False)

        results = []
        for _, row in cat_group.iterrows():
            cat_name = row['category']
            cat_total = round(row['amount'], 2)

            # 2. Subcategories for this category
            sub_df = expenses[expenses['category'] == cat_name]
            sub_group = sub_df.groupby('subcategory')['amount'].sum().abs().reset_index()
            sub_group = sub_group.sort_values('amount', ascending=False)

            subs = []
            for _, sub_row in sub_group.iterrows():
                subs.append({
                    "name": sub_row['subcategory'],
                    "amount": round(sub_row['amount'], 2)
                })

            results.append({
                "category": cat_name,
                "amount": cat_total,
                "subcategories": subs
            })

        return results

    def get_kpi(self) -> Dict[str, float]:
        if self.df.empty:
            return {"total_balance": 0.0, "total_income": 0.0, "total_expense": 0.0}

        return {
            "total_balance": round(float(self.df['amount'].sum() or 0.0), 2),
            "total_income": round(float(self.df.loc[self.df['amount'] > 0, 'amount'].sum() or 0.0), 2),
            "total_expense": round(float(self.df.loc[self.df['amount'] < 0, 'amount'].sum() or 0.0), 2)
        }

import re
import datetime
from pypdf import PdfReader
from typing import Dict, Any, List

class ITTSalaryParser:
    """
    Specialized parser for ITT ITALIA S.r.l. Salary Slips.
    """

    @staticmethod
    def to_float(val: str) -> float:
        if not val: return 0.0
        val = val.strip()
        if val.endswith('-'):
            val = '-' + val[:-1]
        return float(val.replace(".", "").replace(",", "."))

    @classmethod
    def parse(cls, file_path: str) -> Dict[str, Any]:
        reader = PdfReader(file_path)
        text = ""
        for page in reader.pages:
            text += page.extract_text()

        extracted = {
            "employer": "ITT ITALIA S.r.l.",
            "employee_name": "Unknown",
            "net_income": 0.0,
            "total_earnings": 0.0,
            "total_deductions": 0.0,
            "month_reference": "Unknown",
            "date": datetime.date.today(),
            "items": [],
            "leaves": []
        }

        # 1. Header and Basic Info
        patterns = {
            "month_ref": r"([A-Za-z]+\s+\d{4})\s+Pagina\s+1",
            "employee_name": r"Sig\.\s+([A-Z\s]+)\s+\d{4}"
        }

        for key, pattern in patterns.items():
            match = re.search(pattern, text)
            if match:
                if key == "month_ref": 
                    extracted["month_reference"] = match.group(1)
                elif key == "employee_name": 
                    extracted["employee_name"] = match.group(1).strip()

        # 2. Financial Summaries (Aligned vertically)
        # Tot.Comp. and Tot.Trat.
        tot_header_pattern = r"Tot\.Comp\.\s+Tot\.Trat\."
        tot_header_match = re.search(tot_header_pattern, text)
        if tot_header_match:
            after_header = text[tot_header_match.end():].strip()
            lines_after = after_header.split('\n')
            for l in lines_after:
                nums = re.findall(r"[\d\.,]+", l)
                if len(nums) >= 2:
                    extracted["total_earnings"] = cls.to_float(nums[0])
                    extracted["total_deductions"] = cls.to_float(nums[1])
                    break

        # Netto in busta
        netto_header_pattern = r"Netto in busta"
        netto_header_match = re.search(netto_header_pattern, text)
        if netto_header_match:
            after_netto = text[netto_header_match.end():].strip()
            lines_after = after_netto.split('\n')
            for l in lines_after:
                nums = re.findall(r"[\d\.,]+", l)
                if nums:
                    extracted["net_income"] = cls.to_float(nums[-1])
                    break

        # 3. Parsing Table Items (Earnings/Deductions)
        lines = text.split('\n')
        start_parsing_items = False
        stop_parsing_items = False

        for line in lines:
            line = line.strip()
            if "Cod. Descrizione" in line:
                start_parsing_items = True
                continue
            if "Ferie BancaOr" in line or "Tot.Comp." in line:
                stop_parsing_items = True

            if start_parsing_items and not stop_parsing_items and line:
                code_match = re.match(r"^([A-Z0-9/]{4})\s+(.*)$", line)
                if code_match:
                    code = code_match.group(1)
                    rest = code_match.group(2)

                    parts = rest.split()
                    numbers = []

                    processed_idx = len(parts)
                    for i in range(len(parts) - 1, -1, -1):
                        part = parts[i]
                        if re.match(r"^[\d\.,]+-?$", part) and re.search(r"\d", part):
                            numbers.insert(0, cls.to_float(part))
                            processed_idx = i
                        elif part == "X":
                            processed_idx = i
                        else:
                            break

                    description = " ".join(parts[:processed_idx])
                    is_deduction = code.startswith("/") or code in ["076B", "0786"]

                    item = {
                        "code": code,
                        "description": description,
                        "base_data": 0.0,
                        "earnings": 0.0,
                        "deductions": 0.0
                    }

                    if is_deduction:
                        if len(numbers) >= 1: item["deductions"] = numbers[-1]
                        if len(numbers) >= 2: item["base_data"] = numbers[-2]
                    else:
                        if len(numbers) >= 1: item["earnings"] = numbers[-1]
                        if len(numbers) >= 2: item["base_data"] = numbers[-2]
                        # quantity is not explicitly in the model but we could add it if needed

                    extracted["items"].append(item)

        # 4. Parsing Leave Stats
        leave_rows = ["Res.A.P.", "Mat.Anno", "Goduto", "Residuo"]
        leave_cols = ["Ferie", "BancaOr", "ExFes/Rol", "Fless."]
        leaves_dict = {col: {} for col in leave_cols}

        for line in lines:
            line = line.strip()
            for row_label in leave_rows:
                if line.startswith(row_label):
                    content = line[len(row_label):].strip()
                    vals = re.findall(r"[\d\.,]+", content)
                    if len(vals) >= 4:
                        leaves_dict["Ferie"].__setitem__(row_label, cls.to_float(vals[0]))
                        leaves_dict["BancaOr"].__setitem__(row_label, cls.to_float(vals[1]))
                        leaves_dict["ExFes/Rol"].__setitem__(row_label, cls.to_float(vals[2]))
                        leaves_dict["Fless."].__setitem__(row_label, cls.to_float(vals[3]))

        for col, data in leaves_dict.items():
            if data:
                extracted["leaves"].append({
                    "leave_type": col,
                    "previous_residue": data.get("Res.A.P.", 0.0),
                    "accrued": data.get("Mat.Anno", 0.0),
                    "used": data.get("Goduto", 0.0),
                    "remaining": data.get("Residuo", 0.0)
                })

        return extracted

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, FileText, PieChart as AnalyticsIcon, 
  Settings as SettingsIcon, Search, Briefcase, DollarSign,
  Landmark, Trash2, Moon, Sun, ShieldAlert, CheckCircle2,
  Edit2, X, Sparkles, Wand2, PlusCircle, Save
} from 'lucide-react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  BarChart as ReBarChart, Bar, PieChart, Pie, Cell, Legend
} from 'recharts';
import axios from 'axios';
import { themes } from './theme/themeConfig';

const API_BASE_URL = 'http://localhost:8000';
const COLORS = ['#10B981', '#3B82F6', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899', '#6366F1', '#14B8A6'];

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [theme, setTheme] = useState<'lumina' | 'dark'>('lumina');
  const [transactions, setTransactions] = useState<any[]>([]);
  const [salaries, setSalaries] = useState<any[]>([]);
  const [chartData, setChartData] = useState<any[]>([]);
  const [categories, setCategories] = useState<Record<string, string[]>>({});
  const [spendingBreakdown, setSpendingBreakdown] = useState<any[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [kpi, setKpi] = useState({ netWorth: 0, income: 0, expense: 0 });
  const [editingTx, setEditingTx] = useState<any | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<any[]>([]);
  const [showDuplicatesModal, setShowDuplicatesModal] = useState(false);

  // Category Management State
  const [newCategoryName, setNewCategoryName] = useState('');
  const [newSubcategoryName, setNewSubcategoryName] = useState('');
  const [activeCategoryForAdd, setActiveCategoryForAdd] = useState<string | null>(null);

  useEffect(() => {
    fetchData();
    applyTheme(theme);
  }, [theme]);

  const updateCategories = async (newCategories: Record<string, string[]>) => {
    try {
      await axios.post(`${API_BASE_URL}/api/settings/categories`, newCategories);
      setCategories(newCategories);
    } catch (error) {
      alert("Failed to update categories.");
    }
  };

  const handleAddCategory = () => {
    if (!newCategoryName.trim()) return;
    if (categories[newCategoryName.trim()]) {
        alert("Category already exists.");
        return;
    }
    const updated = { ...categories, [newCategoryName.trim()]: [] };
    updateCategories(updated);
    setNewCategoryName('');
  };

  const handleDeleteCategory = (cat: string) => {
      if (!window.confirm(`Delete category "${cat}"?`)) return;
      const updated = { ...categories };
      delete updated[cat];
      updateCategories(updated);
  };

  const handleAddSubcategory = (cat: string) => {
      if (!newSubcategoryName.trim()) return;
      const currentSubs = categories[cat] || [];
      if (currentSubs.includes(newSubcategoryName.trim())) {
          alert("Subcategory already exists.");
          return;
      }
      const updated = { ...categories, [cat]: [...currentSubs, newSubcategoryName.trim()] };
      updateCategories(updated);
      setNewSubcategoryName('');
      setActiveCategoryForAdd(null);
  };

  const handleDeleteSubcategory = (cat: string, sub: string) => {
      if (!window.confirm(`Delete subcategory "${sub}"?`)) return;
      const updated = { ...categories, [cat]: categories[cat].filter(s => s !== sub) };
      updateCategories(updated);
