                    "Luglio": 7, "Agosto": 8, "Settembre": 9, "Ottobre": 10, "Novembre": 11, "Dicembre": 12
                }
                parts = extracted["month_reference"].split()
                if len(parts) == 2 and parts[0] in months:
                    extracted["date"] = datetime.date(int(parts[1]), months[parts[0]], 1)
            except:
                pass

        # Net Pay
        net_match = re.search(r"Netto in busta\s+([\d\.]+,\d{2})", text)
        if net_match:
            extracted["net_income"] = cls.parse_italian_float(net_match.group(1))

        # Contract Hours
        hours_match = re.search(r"Ore Contr\.\s+(\d+)", text)
        if hours_match:
            extracted["contract_hours"] = float(hours_match.group(1))

        # Totals
        tot_header_pattern = r"Tot\.Comp\.\s+Tot\.Trat\."
        tot_header_match = re.search(tot_header_pattern, text)
        if tot_header_match:
            after_header = text[tot_header_match.end():].strip()
            # Find first line with numbers
            lines_after = after_header.split('\n')
            for l in lines_after:
                nums = re.findall(r"[\d\.]+,\d{2}", l)
                if len(nums) >= 2:
                    extracted["total_earnings"] = cls.parse_italian_float(nums[0])
                    extracted["total_deductions"] = cls.parse_italian_float(nums[1])
                    break

    @classmethod
    def _process_financial_page(cls, text: str, extracted: Dict[str, Any]):
        """Handles Page 1: Items, Vacation Grid, Tax."""
        lines = text.split('\n')

        # --- A. PARSE LINE ITEMS ---
        parsing_table = False
        for line in lines:
            if "Cod. Descrizione" in line:
                parsing_table = True
                continue
            if "Tot.Comp." in line or "Ferie" in line:
                parsing_table = False

            if parsing_table and line.strip():
                # Regex to capture: Code, Description, Quantity, Base, Values
                # Attempt to split by spacing logic
                parts = line.split()
                if len(parts) > 2:
                    code = parts[0]

                    # Identify numbers at the end of the line
                    numbers = []
                    desc_end_index = len(parts)

                    # Iterate backwards to find all numbers
                    for i in range(len(parts) - 1, 0, -1):
                        part = parts[i]
                        if re.match(r"^[\d\.]+,\d{4}-?$", part) or re.match(r"^[\d\.]+,\d{2}-?$", part) or part == "X":
                            if part != "X":
                                numbers.insert(0, cls.parse_italian_float(part))
                            desc_end_index = i
                        else:
                            break

                    description = " ".join(parts[1:desc_end_index])

                    # Determine type
                    is_deduction = code.startswith("/") or "Tratt" in line or "Addiz" in line or code in ["076B", "0786"]

                    item = {
                        "code": code,
                        "description": description,
                        "quantity": 0.0,
                        "base_data": 0.0,
                        "earnings": 0.0,
                        "deductions": 0.0,
                        "type": "Deduction" if is_deduction else "Earning"
                    }

                    # Assign numbers based on heuristics (usually Quantity, Base, Amount)
                    # But columns are: Ore/GG | Dato Base | Competenze | Trattenute
                    # If deduction, amount is in Trattenute (last col). If earning, in Competenze.

                    if is_deduction:
                         if len(numbers) >= 1: item["deductions"] = numbers[-1]
                         if len(numbers) >= 2: item["base_data"] = numbers[-2]
                    else:
                         if len(numbers) >= 1: item["earnings"] = numbers[-1]
                         if len(numbers) >= 2: item["base_data"] = numbers[-2]
                         if len(numbers) >= 3: item["quantity"] = numbers[-3]

                    extracted["items"].append(item)

        # --- B. PARSE VACATION GRID ---
        cats = ["Ferie", "BancaOr", "ExFes/Rol", "Fless."]
        # Re-mapping to match DB model
        db_cat_map = {"Ferie": "Ferie", "BancaOr": "Banca Ore", "ExFes/Rol": "ROL/ExFest", "Fless.": "Flessibilita"}

        row_patterns = {
            "previous_residue": r"Res\.A\.P\.\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "accrued": r"Mat\.Anno\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "used": r"Goduto\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "remaining": r"Residuo\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)"
        }

        grid_data = {c: {} for c in cats}
        for r_type, regex in row_patterns.items():
            match = re.search(regex, text)
            if match:
                vals = match.groups()
                for i, cat in enumerate(cats):
                    if i < len(vals):
                        grid_data[cat][r_type] = cls.parse_italian_float(vals[i])

        for cat, data in grid_data.items():
            # Only add if there is data
            if any(v != 0 for v in data.values()):
                extracted["leaves"].append({
                    "leave_type": db_cat_map.get(cat, cat),
                    "previous_residue": data.get("previous_residue", 0.0),
                    "accrued": data.get("accrued", 0.0),
                    "used": data.get("used", 0.0),
                    "remaining": data.get("remaining", 0.0)
                })

        # --- C. PARSE TAX & TFR ---
        # Fiscal Data structure
        fiscal = {
            "taxable_income": 0.0,
            "gross_tax": 0.0,
            "net_tax": 0.0,
            "tfr_month": 0.0,
            "tfr_fund": 0.0
        }

        imp_fisc = re.search(r"Imp\.Fisc.*?(\d[\d\.]*,\d{2})", text, re.DOTALL)
        if imp_fisc: fiscal["taxable_income"] = cls.parse_italian_float(imp_fisc.group(1))

        imp_lord = re.search(r"Imposta L\.\s+(\d[\d\.]*,\d{2})", text) # Imposta Lorda often abbreviated
        if imp_lord: fiscal["gross_tax"] = cls.parse_italian_float(imp_lord.group(1))

        imp_net = re.search(r"Imposta Net.*?(\d[\d\.]*,\d{2})", text, re.DOTALL)
        if imp_net: fiscal["net_tax"] = cls.parse_italian_float(imp_net.group(1))

        tfr_month = re.search(r"TFR Mese\s+([\d\.]*,\d{2})", text)
        if tfr_month: fiscal["tfr_month"] = cls.parse_italian_float(tfr_month.group(1))

        tfr_fund = re.search(r"Q\.TFR Fdo\s+([\d\.]*,\d{2})", text)
        if tfr_fund: fiscal["tfr_fund"] = cls.parse_italian_float(tfr_fund.group(1))

        extracted["fiscal_data"] = fiscal

    @classmethod
    def _process_attendance_page(cls, text: str, extracted: Dict[str, Any]):
        """Handles Page 2/3: Attendance logs."""
        lines = text.split('\n')
        start_reading = False

        for line in lines:
            if "Data entrata" in line:
                start_reading = True
                continue

            if start_reading:
                # Regex for: 01.10.2025 08:00:00 ...
                match = re.search(r"(\d{2}\.\d{2}\.\d{4})\s+(\d{2}:\d{2}:\d{2})\s.*?(\d{2}:\d{2}:\d{2})?", line)
                if match:
                    d_str = match.group(1)
                    try:
                         date_obj = datetime.datetime.strptime(d_str, "%d.%m.%Y").date()
                    except:
                         continue

                    entry = match.group(2)
                    exit_ = match.group(3) if match.group(3) else None

                    extracted["attendance"].append({
                        "date": date_obj,
                        "entry_time": entry,
                        "exit_time": exit_
                    })

