        if self.df.empty:
            return []

        self.df['running_balance'] = self.df['amount'].cumsum()

        # Take last N days or all if less
        daily = self.df.groupby('date')['running_balance'].last().reset_index()
        daily = daily.sort_values('date')

        if len(daily) > days:
            daily = daily.tail(days)

        daily['date'] = daily['date'].dt.strftime('%Y-%m-%d')
        daily.columns = ['date', 'balance']

